sys_script.script:
(function executeRule(current, previous) {

    var qualificationName = current.getValue('name');

    if (!qualificationName) {
        return;
    }

    var normalizedName = qualificationName.trim().toLowerCase();

    var qualification = new GlideRecord(
        'x_2223823_apollo_0_qualification'
    );

    qualification.addQuery(
        'sys_id',
        '!=',
        current.getUniqueValue()
    );

    qualification.query();

    while (qualification.next()) {

        var existingName = qualification.getValue('name');

        if (existingName &&
            existingName.trim().toLowerCase() == normalizedName) {

            gs.addErrorMessage(
                'Qualification "' + qualificationName +
                '" already exists. Duplicate names are not allowed.'
            );

            current.setAbortAction(true);
            return;
        }
    }

})(current, previous);
